import { crc32, deflateSync } from 'node:zlib';

import sharp from 'sharp';

/**
 * Image fixtures for the media pipeline (#305), generated rather than
 * committed: each one is a few lines that say exactly what is in it, where a
 * binary file would say nothing in a diff. Every property a test relies on —
 * the orientation tag, the GPS block, the alpha channel — is read back from
 * the generated bytes by the test that uses it, so a fixture that silently
 * lost one would fail its own assertion rather than make a test pass.
 */

export type FixtureFormat = 'jpeg' | 'png' | 'webp';

/** The EXIF orientations a phone writes, and the rotation the stored pixels need for each to display upright. */
export const ORIENTATION_ROTATIONS: Readonly<Record<1 | 3 | 6 | 8, number>> = {
  1: 0,
  3: 180,
  6: 270,
  8: 90,
};

/**
 * A 300×200 picture that is unambiguous upright: a red square in the top-left
 * corner of a blue field. Upright means red at the top left and blue at the
 * bottom right, whatever the tag said.
 */
async function uprightMarker(): Promise<Buffer> {
  const red = await sharp({
    create: { width: 100, height: 100, channels: 3, background: '#ff0000' },
  })
    .png()
    .toBuffer();
  return sharp({ create: { width: 300, height: 200, channels: 3, background: '#0000ff' } })
    .composite([{ input: red, left: 0, top: 0 }])
    .png()
    .toBuffer();
}

/** GPS for central Baku, in EXIF's rational notation. */
const GPS = {
  GPSLatitudeRef: 'N',
  GPSLatitude: '40/1 24/1 3600/100',
  GPSLongitudeRef: 'E',
  GPSLongitude: '49/1 52/1 1200/100',
};

const XMP =
  '<x:xmpmeta xmlns:x="adobe:ns:meta/"><rdf:RDF xmlns:rdf="http://www.w3.org/1999/02/22-rdf-syntax-ns#">' +
  '<rdf:Description xmlns:exif="http://ns.adobe.com/exif/1.0/" exif:GPSLatitude="40,24.6N"/>' +
  '</rdf:RDF></x:xmpmeta>';

/**
 * The marker, stored rotated and tagged so that a viewer honouring the tag
 * shows it upright — what a phone held sideways writes. Geotagged too.
 */
export async function orientedPhoto(
  format: FixtureFormat,
  orientation: 1 | 3 | 6 | 8,
): Promise<Buffer> {
  return sharp(await uprightMarker())
    .rotate(ORIENTATION_ROTATIONS[orientation])
    .toFormat(format)
    .withMetadata({ orientation })
    .withExifMerge({ IFD3: GPS })
    .toBuffer();
}

/** A 12 MP (4000×3000) camera-sized JPEG with GPS in its EXIF and in XMP. */
export async function geotaggedTwelveMegapixelJpeg(): Promise<Buffer> {
  return sharp({ create: { width: 4000, height: 3000, channels: 3, background: '#7a8c5e' } })
    .jpeg({ quality: 85 })
    .withExif({ IFD0: { Make: 'Fixture', Model: 'Phone' }, IFD3: GPS })
    .withXmp(XMP)
    .toBuffer();
}

/** A PNG whose left half is fully transparent and right half opaque green. */
export async function transparentPng(): Promise<Buffer> {
  const green = await sharp({
    create: { width: 100, height: 200, channels: 4, background: { r: 0, g: 200, b: 0, alpha: 1 } },
  })
    .png()
    .toBuffer();
  return sharp({
    create: { width: 200, height: 200, channels: 4, background: { r: 0, g: 0, b: 0, alpha: 0 } },
  })
    .composite([{ input: green, left: 100, top: 0 }])
    .png()
    .toBuffer();
}

/** A plain image of a given size and format. */
export function solidImage(format: FixtureFormat, width: number, height: number): Promise<Buffer> {
  return sharp({ create: { width, height, channels: 3, background: '#336699' } })
    .toFormat(format)
    .toBuffer();
}

/**
 * A decompression bomb: a valid PNG header declaring 50 000 × 50 000 pixels
 * (2.5 gigapixels, about 7.5 GB decoded) around a few bytes of data. Built by
 * hand, because the point is that its size on disk says nothing about its
 * size in memory, and no encoder would produce it.
 */
export function pixelBombPng(): Buffer {
  const chunk = (type: string, data: Buffer): Buffer => {
    const body = Buffer.concat([Buffer.from(type, 'ascii'), data]);
    const length = Buffer.alloc(4);
    length.writeUInt32BE(data.length);
    const crc = Buffer.alloc(4);
    crc.writeUInt32BE(crc32(body));
    return Buffer.concat([length, body, crc]);
  };
  const ihdr = Buffer.alloc(13);
  ihdr.writeUInt32BE(50_000, 0);
  ihdr.writeUInt32BE(50_000, 4);
  ihdr.writeUInt8(8, 8); // bit depth
  ihdr.writeUInt8(2, 9); // RGB
  return Buffer.concat([
    Buffer.from([0x89, 0x50, 0x4e, 0x47, 0x0d, 0x0a, 0x1a, 0x0a]),
    chunk('IHDR', ihdr),
    chunk('IDAT', deflateSync(Buffer.alloc(64))),
    chunk('IEND', Buffer.alloc(0)),
  ]);
}

/**
 * Whether an EXIF block has a GPS IFD: tag 0x8825 in IFD0. Enough of a TIFF
 * parser to answer that one question, so the fixture's GPS is proved present
 * before the output's absence of it means anything.
 */
export function hasGpsIfd(exif: Buffer): boolean {
  const tiff = exif.subarray(exif.subarray(0, 6).toString('latin1') === 'Exif\0\0' ? 6 : 0);
  const little = tiff.subarray(0, 2).toString('latin1') === 'II';
  const u16 = (offset: number): number =>
    little ? tiff.readUInt16LE(offset) : tiff.readUInt16BE(offset);
  const u32 = (offset: number): number =>
    little ? tiff.readUInt32LE(offset) : tiff.readUInt32BE(offset);
  const ifd0 = u32(4);
  const entries = u16(ifd0);
  for (let i = 0; i < entries; i += 1) {
    if (u16(ifd0 + 2 + i * 12) === 0x8825) {
      return true;
    }
  }
  return false;
}
